1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #e9ecef;
16	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 320px;
20	    max-width: calc(100vw - 32px);
21	    background: #1f2328;
22	    border-radius: 20px;
23	    padding: 20px;
24	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
25	  }
26	  .display {
27	    color: #fff;
28	    font-size: 48px;
29	    text-align: right;
30	    padding: 16px 8px 20px;
31	    min-height: 88px;
32	    overflow: hidden;
33	    white-space: nowrap;
34	    text-overflow: ellipsis;
35	  }
36	  .keys {
37	    display: grid;
38	    grid-template-columns: repeat(4, 1fr);
39	    gap: 12px;
40	  }
41	  button {
42	    font: inherit;
43	    font-size: 24px;
44	    height: 64px;
45	    border: none;
46	    border-radius: 14px;
47	    background: #3a3f45;
48	    color: #fff;
49	    cursor: pointer;
50	  }
51	  button:active { filter: brightness(1.25); }
52	  button.op { background: #f59f00; }
53	  button.op.active { background: #fff; color: #f59f00; }
54	  button.clear { background: #868e96; }
55	  button.wide { grid-column: span 2; }
56	  .tape-bar {
57	    display: flex;
58	    justify-content: space-between;
59	    align-items: center;
60	    color: #adb5bd;
61	    font-size: 14px;
62	  }
63	  .tape-bar button {
64	    font-size: 14px;
65	    height: 28px;
66	    padding: 0 12px;
67	    background: #3a3f45;
68	  }
69	  .tape {
70	    max-height: 132px;
71	    overflow-y: auto;
72	    margin-top: 8px;
73	  }
74	  .tape-row {
75	    display: flex;
76	    justify-content: space-between;
77	    gap: 12px;
78	    padding: 4px 8px;
79	    color: #adb5bd;
80	    font-size: 15px;
81	  }
82	  .tape-expr { overflow-wrap: anywhere; }
83	  .tape-result { color: #fff; white-space: nowrap; }
84	  .tape-result::before { content: "= "; color: #adb5bd; }
85	</style>
86	</head>
87	<body>
88	<div class="calc">
89	  <!-- [REQ-007] Running tape of past calculations, newest first. -->
90	  <div class="tape-bar">
91	    <span>History</span>
92	    <button data-testid="tape-clear">Clear</button>
93	  </div>
94	  <div class="tape" data-testid="calc-tape"></div>
95	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
96	  <div class="keys">
97	    <button class="clear wide" data-testid="key-lparen">(</button>
98	    <button class="clear wide" data-testid="key-rparen">)</button>
99	
100	    <!-- [REQ-006] % key removed; AC spans its place. -->
101	    <button class="clear wide" data-testid="key-clear">AC</button>
102	    <button class="clear" data-testid="key-sign">±</button>
103	    <button class="op" data-testid="key-div" data-op="/">÷</button>
104	
105	    <button data-testid="key-7">7</button>
106	    <button data-testid="key-8">8</button>
107	    <button data-testid="key-9">9</button>
108	    <button class="op" data-testid="key-mul" data-op="*">×</button>
109	
110	    <button data-testid="key-4">4</button>
111	    <button data-testid="key-5">5</button>
112	    <button data-testid="key-6">6</button>
113	    <button class="op" data-testid="key-sub" data-op="-">−</button>
114	
115	    <button data-testid="key-1">1</button>
116	    <button data-testid="key-2">2</button>
117	    <button data-testid="key-3">3</button>
118	    <button class="op" data-testid="key-add" data-op="+">+</button>
119	
120	    <button class="wide" data-testid="key-0">0</button>
121	    <button data-testid="key-dot">.</button>
122	    <button class="op" data-testid="key-equals">=</button>
123	  </div>
124	</div>
125	<script>
126	  var display = document.querySelector('[data-testid="calc-display"]');
127	  var tapeEl = document.querySelector('[data-testid="calc-tape"]');
128	  var OP_SYMBOL = { '+': '+', '-': '−', '*': '×', '/': '÷' };
129	
130	  var state = {
131	    entry: '0',       // text of the number being shown/typed
132	    stored: null,     // left operand
133	    op: null,         // pending operator
134	    fresh: true,      // next digit starts a new entry
135	    typed: false,     // entry was typed by the user (shown as typed, not formatted)
136	    error: false,
137	    groups: [],       // [REQ-005] saved {stored, op, tokens} of each open "(", innermost last
138	    tokens: [],       // [REQ-007] expression text so far, not counting the current operand
139	    operandText: null // [REQ-007] text of the current operand when it is a closed group
140	  };
141	
142	  // [REQ-003] Presentation only: at most 10 significant digits, no trailing
143	  // zeros, exponential when |v| >= 1e10 or < 1e-9. Never applied to stored values.
144	  function formatNumber(v) {
145	    var r = Number(v.toPrecision(10));
146	    if (r === 0) return '0';
147	    var abs = Math.abs(r);
148	    if (abs >= 1e10 || abs < 1e-9) {
149	      return r.toExponential(9).replace(/\.?0+e/, 'e');
150	    }
151	    var e = Math.floor(Math.log10(abs));
152	    var s = r.toFixed(Math.max(0, 10 - e));
153	    if (s.indexOf('.') !== -1) s = s.replace(/0+$/, '').replace(/\.$/, '');
154	    return s;
155	  }
156	
157	  // [REQ-001]
158	  function compute(a, op, b) {
159	    switch (op) {
160	      case '+': return a + b;
161	      case '-': return a - b;
162	      case '*': return a * b;
163	      case '/': return a / b;
164	    }
165	    return b;
166	  }
167	
168	  // [REQ-001]
169	  // [REQ-003] Rounding happens here only; data-value keeps the exact value.
170	  function render() {
171	    var value = Number(state.entry);
172	    display.textContent = state.error ? 'Error' : (state.typed ? state.entry : formatNumber(value));
173	    display.setAttribute('data-value', state.error ? 'NaN' : String(value));
174	    display.setAttribute('data-error', state.error ? 'true' : 'false');
175	    document.querySelectorAll('button[data-op]').forEach(function (b) {
176	      b.classList.toggle('active', state.fresh && state.op === b.getAttribute('data-op'));
177	    });
178	  }
179	
180	  // [REQ-001]
181	  // [REQ-003] Division by zero (non-finite result) enters the error state.
182	  // String(value) is exact: Number(String(v)) === v.
183	  function setResult(value) {
184	    if (!isFinite(value)) {
185	      state.error = true;
186	      state.entry = '0';
187	      state.stored = null;
188	      state.op = null;
189	      state.groups = [];
190	      state.tokens = [];
191	      state.operandText = null;
192	    } else {
193	      state.entry = String(value);
194	    }
195	    state.typed = false;
196	    state.fresh = true;
197	  }
198	
199	  // [REQ-001]
200	  // [REQ-003] Ignored in the error state; only clear leaves it.
201	  // [REQ-004] A value set by ± is finished: the next digit starts a new entry.
202	  function inputDigit(d) {
203	    if (state.error) return;
204	    state.operandText = null;
205	    if (state.fresh || !state.typed) {
206	      state.entry = d;
207	      state.fresh = false;
208	    } else if (state.entry === '0' || state.entry === '-0') {
209	      state.entry = state.entry.slice(0, -1) + d;
210	    } else {
211	      state.entry += d;
212	    }
213	    state.typed = true;
214	  }
215	
216	  // [REQ-001]
217	  // [REQ-003] Ignored in the error state.
218	  function inputDot() {
219	    if (state.error) return;
220	    state.operandText = null;
221	    if (state.fresh || !state.typed) {
222	      state.entry = '0.';
223	      state.fresh = false;
224	    } else if (state.entry.indexOf('.') === -1) {
225	      state.entry += '.';
226	    }
227	    state.typed = true;
228	  }
229	
230	  // [REQ-004] ± flips the current entry. While typing it flips the text, so
231	  // typing continues. Otherwise the flipped value becomes the current operand.
232	  function toggleSign() {
233	    if (state.error) return;
234	    if (state.typed && !state.fresh) {
235	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
236	    } else {
237	      var text = state.operandText;
238	      setOperand(-Number(state.entry));
239	      // [REQ-007] A flipped group reads as -( … ) on the tape.
240	      if (text !== null) state.operandText = text.charAt(0) === '-' ? text.slice(1) : '-' + text;
241	    }
242	  }
243	
244	  // [REQ-004] A finished value that counts as the right operand if an operator
245	  // is waiting (so 2 × ( 3 + 4 ) = is 14), and is replaced by the next digit.
246	  function setOperand(value) {
247	    state.entry = String(value);
248	    state.typed = false;
249	    state.fresh = false;
250	  }
251	
252	  // [REQ-001]
253	  // [REQ-002] Immediate execution: an operator key first finishes the waiting
254	  // operation, strictly left to right, no precedence. 2 + 3 × 4 = is 20.
255	  // [REQ-007] An operator pressed straight after another replaces it on the tape.
256	  function inputOperator(op) {
257	    if (state.error) return;
258	    if (state.op !== null && state.fresh) {
259	      state.tokens[state.tokens.length - 1] = OP_SYMBOL[op];
260	    } else {
261	      state.tokens.push(operandText(), OP_SYMBOL[op]);
262	    }
263	    state.operandText = null;
264	    if (state.op !== null && !state.fresh) {
265	      setResult(compute(state.stored, state.op, Number(state.entry)));
266	      if (state.error) return;
267	    }
268	    state.stored = Number(state.entry);
269	    state.op = op;
270	    state.fresh = true;
271	  }
272	
273	  // [REQ-005] "(" saves the waiting operation and starts an empty group.
274	  // Whatever the group evaluates to replaces the current entry.
275	  function openGroup() {
276	    if (state.error) return;
277	    state.groups.push({ stored: state.stored, op: state.op, tokens: state.tokens });
278	    state.tokens = [];
279	    state.operandText = null;
280	    state.stored = null;
281	    state.op = null;
282	    state.entry = '0';
283	    state.fresh = true;
284	    state.typed = false;
285	  }
286	
287	  // [REQ-005] ")" finishes the innermost group, restores the operation that
288	  // was waiting outside it, and uses the group's value as its right operand.
289	  // Ignored when no group is open.
290	  function closeGroup() {
291	    if (state.error || state.groups.length === 0) return;
292	    var value = state.op === null ? Number(state.entry)
293	      : compute(state.stored, state.op, Number(state.entry));
294	    if (!isFinite(value)) { setResult(value); return; }
295	    var outer = state.groups.pop();
296	    var text = '( ' + state.tokens.concat(operandText()).join(' ') + ' )';
297	    state.stored = outer.stored;
298	    state.op = outer.op;
299	    state.tokens = outer.tokens;
300	    setOperand(value);
301	    state.operandText = text;
302	  }
303	
304	  // [REQ-001]
305	  // [REQ-005] Open groups are closed first, so 2 × ( 3 + 4 = is 14.
306	  // [REQ-007] Each completed calculation adds a tape row. A lone number or an
307	  // error adds nothing.
308	  function equals() {
309	    if (state.error) return;
310	    var grouped = state.groups.length > 0 || state.operandText !== null;
311	    while (state.groups.length > 0 && !state.error) closeGroup();
312	    if (state.error || (state.op === null && !grouped)) return;
313	    var expr = state.tokens.concat(operandText()).join(' ');
314	    var result = state.op === null ? Number(state.entry)
315	      : compute(state.stored, state.op, Number(state.entry));
316	    state.stored = null;
317	    state.op = null;
318	    state.tokens = [];
319	    state.operandText = null;
320	    setResult(result);
321	    if (!state.error) addTapeRow(expr, result);
322	  }
323	
324	  // [REQ-007] Text of the current operand as it appears on the tape.
325	  function operandText() {
326	    if (state.operandText !== null) return state.operandText;
327	    if (state.typed) return state.entry.replace(/\.$/, '');
328	    return formatNumber(Number(state.entry));
329	  }
330	
331	  // [REQ-007] Newest row first. data-value holds the exact result.
332	  function addTapeRow(expr, value) {
333	    var row = document.createElement('div');
334	    row.className = 'tape-row';
335	    row.setAttribute('data-testid', 'tape-row');
336	    var exprEl = document.createElement('span');
337	    exprEl.className = 'tape-expr';
338	    exprEl.setAttribute('data-testid', 'tape-expr');
339	    exprEl.textContent = expr;
340	    var resultEl = document.createElement('span');
341	    resultEl.className = 'tape-result';
342	    resultEl.setAttribute('data-testid', 'tape-result');
343	    resultEl.setAttribute('data-value', String(value));
344	    resultEl.textContent = formatNumber(value);
345	    row.appendChild(exprEl);
346	    row.appendChild(resultEl);
347	    tapeEl.insertBefore(row, tapeEl.firstChild);
348	  }
349	
350	  // [REQ-001]
351	  function clearAll() {
352	    state.entry = '0';
353	    state.stored = null;
354	    state.op = null;
355	    state.fresh = true;
356	    state.typed = false;
357	    state.error = false;
358	    state.groups = [];
359	    state.tokens = [];
360	    state.operandText = null;
361	  }
362	
363	  document.querySelector('.keys').addEventListener('click', function (e) {
364	    var btn = e.target.closest('button');
365	    if (!btn) return;
366	    var id = btn.getAttribute('data-testid');
367	    if (/^key-\d$/.test(id)) inputDigit(id.slice(4));
368	    else if (id === 'key-dot') inputDot();
369	    else if (id === 'key-sign') toggleSign();
370	    else if (id === 'key-lparen') openGroup();
371	    else if (id === 'key-rparen') closeGroup();
372	    else if (id === 'key-equals') equals();
373	    else if (id === 'key-clear') clearAll();
374	    else if (btn.hasAttribute('data-op')) inputOperator(btn.getAttribute('data-op'));
375	    render();
376	  });
377	
378	  // [REQ-007] Empties the tape only; the display is left as it is.
379	  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', function () {
380	    tapeEl.textContent = '';
381	  });
382	
383	  render();
384	</script>
385	</body>
386	</html>
